INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM203DJ80', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'What value of $x$ satisfies $\\frac{6x + 7}{5} = 11$?', NULL, $lyceon_json$[{"key":"A","text":"$8$"},{"key":"B","text":"$-8$"},{"key":"C","text":"$48$"},{"key":"D","text":"$\\frac{2}{3}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Multiply both sides by 5 to get $6x + 7 = 55$. Subtract 7 from both sides: $6x = 48$. Divide by 6: $x = 8$. The value $-8$ results from a sign error when dividing. The value $48$ comes from stopping at the intermediate step $6x = 48$ without dividing by 6. The value $\\frac{2}{3}$ results from neglecting to multiply by 5, incorrectly solving $6x + 7 = 11$ to get $6x = 4$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20AAZ93', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'mcq', E'A survey of $200$ employees found that $74$ commute by car, $53$ commute by train, and $29$ commute by both car and train. If an employee who commutes by car is selected at random, what is the probability that this employee also commutes by train?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{29}{200}$"},{"key":"B","text":"$\\frac{29}{74}$"},{"key":"C","text":"$\\frac{29}{53}$"},{"key":"D","text":"$\\frac{29}{98}$"}]$lyceon_json$::jsonb, 'B', NULL, E'This is a conditional probability question. Given that the employee commutes by car, the sample space is restricted to the $74$ car commuters. Of these, $29$ also commute by train. The conditional probability is $\\frac{29}{74}$. The value $\\frac{29}{200}$ uses the entire survey population as the denominator instead of conditioning on car commuters. The value $\\frac{29}{53}$ incorrectly conditions on train commuters rather than car commuters. The value $\\frac{29}{98}$ uses $74 + 53 - 29 = 98$ (the union) as the denominator, confusing the union with the given condition.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20KPO3B', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has a diameter of $26$ cm. What is the circumference of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$13\\pi$ cm"},{"key":"B","text":"$26\\pi$ cm"},{"key":"C","text":"$52\\pi$ cm"},{"key":"D","text":"$169\\pi$ cm"}]$lyceon_json$::jsonb, 'B', NULL, E'The circumference of a circle is $C = \\pi d = 26\\pi$ cm. The answer $13\\pi$ comes from using the radius ($13$) with the formula $C = \\pi r$ instead of $C = 2\\pi r$, an incorrect formula. The answer $52\\pi$ comes from using $C = 2\\pi d$ instead of $C = \\pi d$, doubling unnecessarily. The answer $169\\pi$ comes from computing the area formula $\\pi r^2 = \\pi(13^2) = 169\\pi$ instead of the circumference.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20YEUUL', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'grid_in', E'The function $h(x) = -x^2 + 18x - 74$. What is the maximum value of $h(x)$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'Completing the square: $h(x) = -(x^2 - 18x) - 74 = -(x^2 - 18x + 81) + 81 - 74 = -(x - 9)^2 + 7$. Since $-(x - 9)^2 \\leq 0$ for all real $x$, the maximum occurs when $(x - 9)^2 = 0$, i.e., when $x = 9$. The maximum value is $h(9) = 7$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21UZYNF', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'mcq', E'What are the solutions to $x^2 - 13x + 42 = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$x = 3$ and $x = 14$"},{"key":"B","text":"$x = -6$ and $x = -7$"},{"key":"C","text":"$x = 6$ and $x = 7$"},{"key":"D","text":"$x = -6$ and $x = 7$"}]$lyceon_json$::jsonb, 'C', NULL, E'Factoring $x^2 - 13x + 42$: find two numbers that multiply to $42$ and add to $-13$. Those numbers are $-6$ and $-7$, so the equation factors as $(x - 6)(x - 7) = 0$, giving $x = 6$ and $x = 7$. The pair $x = 3$ and $x = 14$ multiply to $42$ but sum to $17$, not $13$. The pair $x = -6$ and $x = -7$ reverses the signs of the correct roots. The pair $x = -6$ and $x = 7$ gives the wrong sign on one root.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21WWK4K', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'grid_in', E'A line passes through the points $(2, 11)$ and $(5, 29)$. What is the $y$-intercept of this line?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-1', ARRAY['-1'], E'First find the slope: $m = \\frac{29 - 11}{5 - 2} = \\frac{18}{3} = 6$. Using point-slope form with $(2, 11)$: $y - 11 = 6(x - 2)$, which simplifies to $y = 6x - 12 + 11 = 6x - 1$. The $y$-intercept is $-1$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM247WK4K', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'In a class of $31$ students, $18$ play basketball and $11$ play volleyball. If $5$ students play both sports, what is the probability that a randomly selected student plays neither basketball nor volleyball?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{7}{31}$"},{"key":"B","text":"$\\frac{2}{31}$"},{"key":"C","text":"$\\frac{12}{31}$"},{"key":"D","text":"$\\frac{24}{31}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Using the inclusion-exclusion principle, the number of students who play at least one sport is $18 + 11 - 5 = 24$. The number who play neither is $31 - 24 = 7$, so the probability is $\\frac{7}{31}$. The value $\\frac{2}{31}$ results from subtracting $18 + 11 = 29$ from $31$ without adding back the overlap of $5$. The value $\\frac{12}{31}$ comes from subtracting only the basketball count minus the overlap ($18 - 5 = 13$) from $31$ and ignoring volleyball entirely. The value $\\frac{24}{31}$ gives the probability of playing at least one sport, not the probability of playing neither.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24KQPEL', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'grid_in', E'A town''s population was $8{,}500$ at the start of $2021$. The population increased by $20\\%$ during $2021$ and then decreased by $15\\%$ during $2022$. What was the population at the end of $2022$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '8670', ARRAY['8670'], E'After a $20\\%$ increase, the population is $8{,}500 \\times 1.20 = 10{,}200$. After a $15\\%$ decrease, the population is $10{,}200 \\times 0.85 = 8{,}670$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24X22EX', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'grid_in', E'A surveyor standing on level ground measures the angle of elevation to the top of a building as $53°$. The surveyor is $27$ meters from the base of the building. What is the height of the building, in meters, rounded to the nearest whole number? (Use $\\tan(53°) \\approx 1.327$.)', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '36', ARRAY['36'], E'The height of the building is the side opposite the $53°$ angle, and the distance from the base is the adjacent side. Using the tangent ratio, $\\tan(53°) = \\frac{\\text{height}}{27}$, so the height $= 27 \\times \\tan(53°) = 27 \\times 1.327 \\approx 35.83$. Rounded to the nearest whole number, the height is $36$ meters.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM260VUH3', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'A circle in the $xy$-plane has center $(-5, 8)$ and passes through the point $(-5, 15)$. Which of the following is an equation of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$(x + 5)^2 + (y - 8)^2 = 7$"},{"key":"B","text":"$(x - 5)^2 + (y + 8)^2 = 49$"},{"key":"C","text":"$(x + 5)^2 + (y - 8)^2 = 49$"},{"key":"D","text":"$(x + 5)^2 + (y - 8)^2 = 225$"}]$lyceon_json$::jsonb, 'C', NULL, E'The radius is the distance from the center $(-5, 8)$ to the point $(-5, 15)$: $r = |15 - 8| = 7$. The standard equation of a circle with center $(h, k)$ and radius $r$ is $(x - h)^2 + (y - k)^2 = r^2$, so the equation is $(x + 5)^2 + (y - 8)^2 = 49$. The equation $(x + 5)^2 + (y - 8)^2 = 7$ uses the radius $7$ without squaring it. The equation $(x - 5)^2 + (y + 8)^2 = 49$ has the wrong signs on both center coordinates. The equation $(x + 5)^2 + (y - 8)^2 = 225$ uses $15^2 = 225$ as the radius squared, confusing the $y$-coordinate of the given point with the radius.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26RDOJ8', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which of the following is equivalent to $\\frac{4x^2 - 25}{2x + 5}$ for all values of $x$ where the expression is defined?', NULL, $lyceon_json$[{"key":"A","text":"$2x + 5$"},{"key":"B","text":"$2x - 5$"},{"key":"C","text":"$4x - 5$"},{"key":"D","text":"$2x^2 - 5$"}]$lyceon_json$::jsonb, 'B', NULL, E'The numerator $4x^2 - 25$ is a difference of squares: $(2x)^2 - 5^2 = (2x + 5)(2x - 5)$. Dividing by $(2x + 5)$ cancels one factor, leaving $2x - 5$. The expression $2x + 5$ incorrectly assumes the remaining factor matches the denominator. The expression $4x - 5$ results from an arithmetic error in factoring the coefficient of $x$. The expression $2x^2 - 5$ comes from dividing only the constant terms and partially reducing the $x^2$ term.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27ZO42O', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A researcher wants to determine whether a new fertilizer increases tomato plant growth. She randomly assigns $40$ tomato plants to two groups: one group receives the new fertilizer and the other receives no fertilizer. After $6$ weeks, she measures the height of each plant. What type of study is the researcher conducting?', NULL, $lyceon_json$[{"key":"A","text":"An observational study"},{"key":"B","text":"A survey"},{"key":"C","text":"An experiment"},{"key":"D","text":"A census"}]$lyceon_json$::jsonb, 'C', NULL, E'Because the researcher randomly assigns plants to treatment and control groups and applies a treatment (the fertilizer), this is an experiment. An observational study would involve observing existing differences without imposing a treatment. A survey collects self-reported data from respondents, which does not apply to measuring plant heights. A census attempts to collect data from every member of a population, not from a sample with an imposed treatment.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2B8HQ9Y', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'mcq', E'A data set of $40$ values has a mean of $57$ and a standard deviation of $8$. Every value in the data set is multiplied by $3$ and then $11$ is added to each result. What are the new mean and new standard deviation?', NULL, $lyceon_json$[{"key":"A","text":"Mean $= 182$, standard deviation $= 24$"},{"key":"B","text":"Mean $= 182$, standard deviation $= 35$"},{"key":"C","text":"Mean $= 171$, standard deviation $= 24$"},{"key":"D","text":"Mean $= 171$, standard deviation $= 8$"}]$lyceon_json$::jsonb, 'A', NULL, E'When every value is multiplied by $3$, both the mean and standard deviation are multiplied by $3$: new mean $= 57 \\times 3 = 171$, new SD $= 8 \\times 3 = 24$. When $11$ is added to every value, the mean increases by $11$ but the standard deviation is unchanged: final mean $= 171 + 11 = 182$, final SD $= 24$. The answer with mean $182$ and SD $35$ incorrectly adds $11$ to the standard deviation as well. The answer with mean $171$ and SD $24$ omits the addition of $11$ to the mean. The answer with mean $171$ and SD $8$ applies neither the multiplication to the SD nor the addition to the mean correctly.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BDE7HK', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'Which value of $x$ satisfies the inequality $5x - 9 > 26$?', NULL, $lyceon_json$[{"key":"A","text":"6"},{"key":"B","text":"7"},{"key":"C","text":"8"},{"key":"D","text":"5"}]$lyceon_json$::jsonb, 'C', NULL, E'Solving the inequality 5x - 9 > 26 requires adding 9 to both sides to get 5x > 35, then dividing both sides by 5 to get x > 7. Among the given values, 8 is the only value greater than 7 and therefore satisfies the inequality. The value 7 does not satisfy the inequality because the inequality is strict (greater than, not greater than or equal to). The values 6 and 5 are both less than 7 and do not satisfy the inequality.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2C14Y3W', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function $g$ is defined by $g(x) = (x - 9)^2 + 4$. What is the minimum value of $g(x)$?', NULL, $lyceon_json$[{"key":"A","text":"$9$"},{"key":"B","text":"$-4$"},{"key":"C","text":"$0$"},{"key":"D","text":"$4$"}]$lyceon_json$::jsonb, 'D', NULL, E'The function $g(x) = (x - 9)^2 + 4$ is in vertex form. Since $(x - 9)^2 \\geq 0$ for all real $x$, the smallest value of $(x - 9)^2$ is $0$, occurring when $x = 9$. Therefore the minimum value of $g(x)$ is $0 + 4 = 4$. The value $9$ is the $x$-coordinate of the vertex, not the minimum output. The value $-4$ introduces a sign error on the constant term. The value $0$ incorrectly assumes the minimum of a squared expression plus a constant is always $0$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ENL6XP', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A factory produces $174$ bolts every $3$ minutes. At this rate, how many bolts does the factory produce in $21$ minutes?', NULL, $lyceon_json$[{"key":"A","text":"$1{,}218$"},{"key":"B","text":"$1{,}044$"},{"key":"C","text":"$1{,}392$"},{"key":"D","text":"$522$"}]$lyceon_json$::jsonb, 'A', NULL, E'The rate is $\\frac{174}{3} = 58$ bolts per minute. In $21$ minutes the factory produces $58 \\times 21 = 1{,}218$ bolts. The value $1{,}044$ results from incorrectly computing $58 \\times 18$, confusing the time multiplier. The value $1{,}392$ comes from multiplying $174 \\times 8$ instead of using the correct unit rate and time. The value $522$ results from multiplying $174 \\times 3$ instead of multiplying the unit rate by $21$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FNNLJK', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'A university conducts a study to test whether background music improves reading comprehension. Researchers recruit $90$ volunteers from the psychology department and randomly assign them to three groups: silence, classical music, and pop music. Each group reads the same passage and takes a comprehension test. The classical music group scores significantly higher than the other two groups. Which of the following is a valid concern about generalizing the results of this study?', NULL, $lyceon_json$[{"key":"A","text":"The study used random assignment, so the results cannot establish causation."},{"key":"B","text":"The volunteers were recruited from a single department, which may limit generalizability to the broader population."},{"key":"C","text":"The study should have used a larger margin of error to account for variability."},{"key":"D","text":"The study is invalid because it did not include a placebo group."}]$lyceon_json$::jsonb, 'B', NULL, E'The study uses random assignment, so it can establish causation within the study population. However, because all volunteers come from the psychology department (a convenience sample), the results may not generalize to the broader university population or to people outside the university. The claim that random assignment prevents establishing causation reverses the purpose of random assignment: it is precisely what allows causal conclusions. The suggestion to use a larger margin of error confuses experimental design with sampling inference and is not a valid concern about generalizability. The claim that the study needs a placebo group is not applicable here because the silence condition serves as the control, and there is no treatment being disguised.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2G9NKZS', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'A shipping company charges a flat fee of 11 dollars plus 4 dollars per pound for packages. A customer has at most 59 dollars to spend on shipping. Which inequality represents the number of pounds $p$ the customer can ship?', NULL, $lyceon_json$[{"key":"A","text":"$4p + 11 \\leq 59$"},{"key":"B","text":"$4p + 11 \\geq 59$"},{"key":"C","text":"$11p + 4 \\leq 59$"},{"key":"D","text":"$4p - 11 \\leq 59$"}]$lyceon_json$::jsonb, 'A', NULL, E'The total cost is the flat fee of 11 dollars plus 4 dollars per pound, giving $4p + 11$. Since the customer can spend at most 59 dollars, the cost must be less than or equal to 59, so $4p + 11 \\leq 59$. The inequality $4p + 11 \\geq 59$ reverses the direction, implying the customer must spend at least 59 dollars. The expression $11p + 4$ swaps the coefficient and constant, misidentifying which value is per-pound. The expression $4p - 11$ subtracts the flat fee instead of adding it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HT7FPE', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'grid_in', E'If $(3x + 7)(3x - 7) - (3x - 2)^2 = ax + b$ for all values of $x$, what is the value of $a + b$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-41', ARRAY['-41'], E'Expanding $(3x + 7)(3x - 7)$ using the difference of squares gives $9x^2 - 49$. Expanding $(3x - 2)^2$ gives $9x^2 - 12x + 4$. Subtracting: $(9x^2 - 49) - (9x^2 - 12x + 4) = 9x^2 - 49 - 9x^2 + 12x - 4 = 12x - 53$. Therefore $a = 12$ and $b = -53$, so $a + b = 12 + (-53) = -41$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HV4DEU', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'grid_in', E'A solution is prepared by mixing compound A and compound B in a ratio of $7:11$ by mass. A chemist has $539$ grams of compound B and wants to use all of it. After mixing, she removes $\\frac{1}{9}$ of the total solution. How many grams of solution remain?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '784', ARRAY['784'], E'The ratio of A to B is $7:11$. If $B = 539$ grams, then $A = \\frac{7}{11} \\times 539 = 343$ grams. The total solution is $343 + 539 = 882$ grams. Removing $\\frac{1}{9}$ of the total means removing $\\frac{882}{9} = 98$ grams. The remaining solution is $882 - 98 = 784$ grams.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IXTWYD', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'mcq', E'From a point $A$ on level ground, the angle of elevation to the top of a tower is $25°$. After walking $40$ meters directly toward the tower to point $B$, the angle of elevation becomes $50°$. Which of the following is closest to the height of the tower, in meters? (Use $\\tan(25°) \\approx 0.466$ and $\\tan(50°) \\approx 1.192$.)', NULL, $lyceon_json$[{"key":"A","text":"$19$"},{"key":"B","text":"$26$"},{"key":"C","text":"$31$"},{"key":"D","text":"$48$"}]$lyceon_json$::jsonb, 'C', NULL, E'Let $h$ be the height and $d$ be the initial distance from the base. From point $A$: $\\tan(25°) = h/d$, so $h = 0.466d$. From point $B$: $\\tan(50°) = h/(d - 40)$, so $h = 1.192(d - 40)$. Setting these equal: $0.466d = 1.192d - 47.68$, giving $0.726d = 47.68$, so $d \\approx 65.7$ and $h = 0.466 \\times 65.7 \\approx 30.6 \\approx 31$. The answer $19$ comes from incorrectly using $h = 40 \\times \\tan(25°) = 18.6$, treating the walked distance as the full base. The answer $26$ results from an arithmetic error during the system of equations. The answer $48$ comes from using $h = 40 \\times \\tan(50°) = 47.7$, again treating the walked distance as the full base with the wrong angle.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JDYZ2D', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A researcher surveys a random sample of $400$ voters and finds that $47\\%$ plan to vote for Candidate X. The margin of error for the survey is $3\\%$. A second researcher surveys a random sample of $1{,}600$ voters from the same population and also finds that $47\\%$ plan to vote for Candidate X. Which of the following best compares the margins of error of the two surveys?', NULL, $lyceon_json$[{"key":"A","text":"The second survey's margin of error is approximately half that of the first survey."},{"key":"B","text":"The second survey's margin of error is approximately one-fourth that of the first survey."},{"key":"C","text":"Both surveys have the same margin of error because the sample proportion is the same."},{"key":"D","text":"The second survey's margin of error is approximately twice that of the first survey."}]$lyceon_json$::jsonb, 'A', NULL, E'The margin of error is inversely proportional to the square root of the sample size. Since $1{,}600$ is $4$ times $400$, $\\sqrt{4} = 2$, so the margin of error of the second survey is approximately $\\frac{1}{2}$ that of the first, or about $1.5\\%$. The claim that it is one-fourth confuses the ratio of sample sizes ($4$) with the ratio of margins of error, ignoring the square root relationship. The claim that both margins are equal incorrectly assumes the margin depends only on the sample proportion and not the sample size. The claim that the second margin is double reverses the relationship between sample size and margin of error.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JQ4L1I', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'grid_in', E'The function $f(x) = -3x + 47$ models the number of gallons of water remaining in a tank after $x$ minutes. After how many minutes will the tank contain exactly 11 gallons?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '12', ARRAY['12'], E'Set $f(x) = 11$: the equation becomes $-3x + 47 = 11$. Subtract 47 from both sides to get $-3x = -36$. Divide both sides by $-3$ to find $x = 12$. The tank will contain exactly 11 gallons after 12 minutes.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KTBMQG', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'What is the $y$-intercept of the line $3x - 7y = 42$?', NULL, $lyceon_json$[{"key":"A","text":"$-6$"},{"key":"B","text":"$6$"},{"key":"C","text":"$14$"},{"key":"D","text":"$\\frac{3}{7}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The $y$-intercept occurs when $x = 0$. Substituting gives $-7y = 42$, so $y = -6$. The value $6$ results from dropping the negative sign when dividing $42$ by $-7$. The value $14$ comes from finding the $x$-intercept instead, setting $y = 0$ and solving $3x = 42$. The value $\\frac{3}{7}$ is the slope of the line, not the $y$-intercept.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LZNK55', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'mcq', E'A line of best fit for a scatterplot is given by $y = 2.3x + 14$. According to this model, what is the predicted value of $y$ when $x = 9$?', NULL, $lyceon_json$[{"key":"A","text":"$34.7$"},{"key":"B","text":"$20.7$"},{"key":"C","text":"$25.3$"},{"key":"D","text":"$38.0$"}]$lyceon_json$::jsonb, 'A', NULL, E'Substituting $x = 9$: $y = 2.3(9) + 14 = 20.7 + 14 = 34.7$. The value $20.7$ is only the product $2.3 \\times 9$ without adding the $y$-intercept of $14$. The value $25.3$ results from adding $2.3 + 9 + 14$ instead of multiplying the slope by $x$. The value $38.0$ comes from using an incorrect slope value in the calculation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NMTL26', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'grid_in', E'If $9x + 14 = 77$, what is the value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'Subtract 14 from both sides to get $9x = 63$. Then divide both sides by 9 to find $x = 7$.', NULL, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NZKM8W', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'mcq', E'A triangle has a base of $22$ cm and a height of $13$ cm. What is the area, in square centimeters, of the triangle?', NULL, $lyceon_json$[{"key":"A","text":"$35$"},{"key":"B","text":"$143$"},{"key":"C","text":"$176$"},{"key":"D","text":"$286$"}]$lyceon_json$::jsonb, 'B', NULL, E'The area of a triangle is $\\frac{1}{2} \\times \\text{base} \\times \\text{height} = \\frac{1}{2} \\times 22 \\times 13 = 143$ square centimeters. The answer $35$ comes from adding the base and height instead of multiplying, a fundamental formula confusion. The answer $176$ results from a multiplication error ($22 \\times 13$ miscalculated as $352$, then halved to $176$). The answer $286$ comes from computing $22 \\times 13 = 286$ but forgetting to multiply by $\\frac{1}{2}$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OAL5JI', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'mcq', E'A scatterplot shows the relationship between advertising spend ($x$, in thousands of dollars) and revenue ($y$, in thousands of dollars) for $14$ months. The equation of the line of best fit is $y = 4.7x + 31$, and the correlation coefficient is $r = 0.91$. In one month the company spent $18$ thousand dollars on advertising and earned $127$ thousand dollars in revenue. Which of the following best describes the residual for that month and the overall strength of the model?', NULL, $lyceon_json$[{"key":"A","text":"The residual is $11.4$ thousand dollars, and the model is a strong fit."},{"key":"B","text":"The residual is $-11.4$ thousand dollars, and the model is a strong fit."},{"key":"C","text":"The residual is $11.4$ thousand dollars, and the model is a weak fit."},{"key":"D","text":"The residual is $42.6$ thousand dollars, and the model is a strong fit."}]$lyceon_json$::jsonb, 'A', NULL, E'The predicted revenue is $y = 4.7(18) + 31 = 84.6 + 31 = 115.6$ thousand dollars. The residual is actual minus predicted: $127 - 115.6 = 11.4$ thousand dollars. Since $r = 0.91$ is close to $1$, the linear model is a strong fit. The answer stating a residual of $-11.4$ incorrectly computes predicted minus actual instead of actual minus predicted. The answer describing the model as a weak fit misinterprets $r = 0.91$, which indicates strong positive linear association. The answer with a residual of $42.6$ omits the intercept when computing the predicted value, using only $127 - 84.6$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OSC3D6', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 1, 'grid_in', E'What is the value of $x$ in the solution to the system of equations below?
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OXL8I4', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'A polling organization surveys a random sample of adults in a town and reports that $39\\%$ favor a proposed zoning change, with a margin of error of $\\pm 5\\%$ at a $95\\%$ confidence level. Which of the following conclusions is best supported by this result?', NULL, $lyceon_json$[{"key":"A","text":"It is certain that between $34\\%$ and $44\\%$ of all adults in the town favor the zoning change."},{"key":"B","text":"The polling organization is $95\\%$ confident that the true proportion of all adults in the town who favor the zoning change is between $34\\%$ and $44\\%$."},{"key":"C","text":"Exactly $39\\%$ of all adults in the town favor the zoning change."},{"key":"D","text":"If the poll were repeated many times, approximately $39\\%$ of those polls would show a majority in favor."}]$lyceon_json$::jsonb, 'B', NULL, E'A $95\\%$ confidence interval means that we are $95\\%$ confident the true population proportion falls between $39\\% - 5\\% = 34\\%$ and $39\\% + 5\\% = 44\\%$. The statement that it is certain the true value lies in this range overstates the confidence level; a $95\\%$ confidence level does not imply certainty. The claim that exactly $39\\%$ favor the change confuses the sample statistic with the population parameter. The statement about $39\\%$ of repeated polls showing a majority misinterprets both the confidence level and what the statistic measures.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OY21PM', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'In triangle $ABC$, the exterior angle at vertex $C$ measures $127°$. If angle $A$ measures $51°$, what is the measure, in degrees, of angle $B$?', NULL, $lyceon_json$[{"key":"A","text":"$53°$"},{"key":"B","text":"$71°$"},{"key":"C","text":"$76°$"},{"key":"D","text":"$129°$"}]$lyceon_json$::jsonb, 'C', NULL, E'By the exterior angle theorem, an exterior angle of a triangle equals the sum of the two non-adjacent interior angles. Therefore $127° = 51° + B$, giving $B = 76°$. The answer $53°$ is the interior angle at $C$ ($180° - 127°$), which results from finding the wrong angle. The answer $71°$ comes from a subtraction error ($127 - 51 = 71$ instead of $76$). The answer $129°$ comes from adding $51°$ to something rather than subtracting, confusing the relationship between interior and exterior angles.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PI4UYV', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'mcq', E'A jacket originally costs 47 dollars. During a sale, the price is reduced by $20\\%$. What is the sale price of the jacket, in dollars?', NULL, $lyceon_json$[{"key":"A","text":"$37.60$"},{"key":"B","text":"$27.00$"},{"key":"C","text":"$42.30$"},{"key":"D","text":"$9.40$"}]$lyceon_json$::jsonb, 'A', NULL, E'The discount is $47 \\times 0.20 = 9.40$ dollars. The sale price is $47 - 9.40 = 37.60$ dollars. The value $27.00$ results from an arithmetic error when subtracting the discount from the original price. The value $42.30$ comes from mistakenly applying a $10\\%$ discount instead of $20\\%$. The value $9.40$ is the discount amount itself, not the reduced sale price.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2POWLXE', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'grid_in', E'If $x^2 + 10x = 56$, what is the positive value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '4', ARRAY['4'], E'Rewriting as $x^2 + 10x - 56 = 0$ and factoring: find two numbers that multiply to $-56$ and add to $10$. Those are $14$ and $-4$, so $(x + 14)(x - 4) = 0$. The solutions are $x = -14$ and $x = 4$. The positive value is $4$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QGLMV8', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'grid_in', E'A rectangular prism has a length of $13$ cm, a width of $4$ cm, and a height of $7$ cm. A second rectangular prism has twice the length, the same width, and half the height of the first. What is the volume, in cubic centimeters, of the second prism?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '364', ARRAY['364'], E'The second prism has length $2 \\times 13 = 26$ cm, width $4$ cm, and height $\\frac{7}{2} = 3.5$ cm. Its volume is $26 \\times 4 \\times 3.5 = 364$ cubic centimeters.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QSLM3C', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'mcq', E'What is the solution to $\\frac{7x + 3}{2} - \\frac{x - 5}{6} = 2x + 9$?', NULL, $lyceon_json$[{"key":"A","text":"$5$"},{"key":"B","text":"$-5$"},{"key":"C","text":"$\\frac{25}{4}$"},{"key":"D","text":"$40$"}]$lyceon_json$::jsonb, 'A', NULL, E'Multiply every term by 6 (the LCD): $3(7x + 3) - (x - 5) = 6(2x + 9)$. Distribute: $21x + 9 - x + 5 = 12x + 54$, giving $20x + 14 = 12x + 54$. Subtract $12x$ and $14$: $8x = 40$, so $x = 5$. The value $-5$ results from a sign error when isolating $x$. The value $\\frac{25}{4}$ results from incorrectly distributing the negative sign, writing $-x - 5$ instead of $-x + 5$, which leads to $8x = 50$. The value $40$ comes from stopping at $8x = 40$ without dividing by 8.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2R3DKHI', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'grid_in', E'In the $xy$-plane, a circle has the equation $x^2 + y^2 - 6x + 10y - 47 = 0$. What is the radius of the circle?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '9', ARRAY['9'], E'Rewrite the equation by completing the square. Group the $x$ and $y$ terms: $(x^2 - 6x) + (y^2 + 10y) = 47$. Complete the square for $x$: $x^2 - 6x + 9 = (x - 3)^2$. Complete the square for $y$: $y^2 + 10y + 25 = (y + 5)^2$. Add $9$ and $25$ to both sides: $(x - 3)^2 + (y + 5)^2 = 47 + 9 + 25 = 81$. Since $81 = 9^2$, the radius is $9$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RC2QOU', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'For the system of equations $y = x^2 - 6x + 11$ and $y = 3x - 7$, what is the sum of the $x$-coordinates of all solutions?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$9$"},{"key":"C","text":"$18$"},{"key":"D","text":"$-9$"}]$lyceon_json$::jsonb, 'B', NULL, E'Setting the expressions equal: $x^2 - 6x + 11 = 3x - 7$, which simplifies to $x^2 - 9x + 18 = 0$. Factoring gives $(x - 3)(x - 6) = 0$, so $x = 3$ and $x = 6$. The sum of the $x$-coordinates is $3 + 6 = 9$. By Vieta''s formulas, the sum of roots of $x^2 - 9x + 18 = 0$ is also $9$. The value $3$ represents only one of the two solutions. The value $18$ is the product of the roots, not their sum. The value $-9$ results from a sign error in applying Vieta''s formulas.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RJUP27', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'Line $p$ has equation $5x - 2y = 18$. Line $q$ is perpendicular to line $p$ and passes through the point $(10, 3)$. What is the $y$-intercept of line $q$?', NULL, $lyceon_json$[{"key":"A","text":"$7$"},{"key":"B","text":"$-7$"},{"key":"C","text":"$-22$"},{"key":"D","text":"$-1$"}]$lyceon_json$::jsonb, 'A', NULL, E'Rewrite line $p$ as $y = \\frac{5}{2}x - 9$, so its slope is $\\frac{5}{2}$. The perpendicular slope is $-\\frac{2}{5}$. Using point-slope form: $y - 3 = -\\frac{2}{5}(x - 10)$, giving $y = -\\frac{2}{5}x + 4 + 3 = -\\frac{2}{5}x + 7$. The $y$-intercept is $7$. The value $-7$ results from a sign error in combining $4 + 3$. The value $-22$ comes from using the same slope $\\frac{5}{2}$ (parallel) instead of the perpendicular slope, yielding $y = \\frac{5}{2}x - 22$. The value $-1$ results from using $\\frac{2}{5}$ instead of $-\\frac{2}{5}$ for the perpendicular slope, omitting the sign change.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RMGXU3', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'A health researcher observes that among $1{,}200$ adult participants, those who drink green tea daily have lower blood pressure on average than those who do not. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"Drinking green tea daily causes lower blood pressure."},{"key":"B","text":"There is an association between daily green tea consumption and lower blood pressure."},{"key":"C","text":"Adults who do not drink green tea should begin drinking it to lower their blood pressure."},{"key":"D","text":"The study proves that green tea has no effect on blood pressure."}]$lyceon_json$::jsonb, 'B', NULL, E'Because this is an observational study (no random assignment of participants to treatment groups), the researcher can only conclude that an association exists between green tea consumption and lower blood pressure. The causal claim that green tea causes lower blood pressure is not supported because confounding variables (such as overall diet and exercise habits) may explain the difference. The recommendation to begin drinking green tea assumes causation and goes beyond what the data support. The claim that the study proves no effect directly contradicts the observed association.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RQTN4I', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'A gym charges a one-time registration fee of 37 dollars plus 19 dollars per month. Which function $f(m)$ gives the total cost, in dollars, after $m$ months?', NULL, $lyceon_json$[{"key":"A","text":"$f(m) = 19m + 37$"},{"key":"B","text":"$f(m) = 37m + 19$"},{"key":"C","text":"$f(m) = 19m - 37$"},{"key":"D","text":"$f(m) = 56m$"}]$lyceon_json$::jsonb, 'A', NULL, E'The monthly charge of 19 dollars is the rate of change (slope), and the one-time fee of 37 dollars is the initial value ($y$-intercept), giving $f(m) = 19m + 37$. The function $37m + 19$ swaps the rate and the initial fee. The function $19m - 37$ uses the wrong sign for the registration fee, subtracting it instead of adding. The function $56m$ incorrectly combines the rate and fee into a single coefficient, treating the entire amount as a monthly rate.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RRRI1E', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'In a right triangle, one of the acute angles measures $32°$. What is the measure, in degrees, of the other acute angle?', NULL, $lyceon_json$[{"key":"A","text":"$48°$"},{"key":"B","text":"$58°$"},{"key":"C","text":"$64°$"},{"key":"D","text":"$148°$"}]$lyceon_json$::jsonb, 'B', NULL, E'In a right triangle, the two acute angles are complementary, meaning they sum to $90°$. Therefore the other acute angle is $90° - 32° = 58°$. The answer $48°$ results from a subtraction error. The answer $64°$ comes from doubling $32°$ instead of subtracting from $90°$, an incorrect setup. The answer $148°$ comes from subtracting from $180°$ instead of $90°$, confusing supplementary angles with the right-triangle acute-angle relationship.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SFNLMC', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'mcq', E'In the figure, triangle $RST$ has an exterior angle at vertex $T$. The measure of angle $R$ is $(2x + 11)°$, the measure of angle $S$ is $(3x - 4)°$, and the measure of the exterior angle at $T$ is $(7x - 29)°$. What is the measure, in degrees, of the interior angle at $T$?', NULL, $lyceon_json$[{"key":"A","text":"$47°$"},{"key":"B","text":"$50°$"},{"key":"C","text":"$83°$"},{"key":"D","text":"$97°$"}]$lyceon_json$::jsonb, 'C', NULL, E'By the exterior angle theorem, the exterior angle at $T$ equals the sum of the two remote interior angles: $7x - 29 = (2x + 11) + (3x - 4)$, which simplifies to $7x - 29 = 5x + 7$, so $2x = 36$ and $x = 18$. The exterior angle at $T$ is $7(18) - 29 = 97°$, so the interior angle at $T$ is $180° - 97° = 83°$. The answer $47°$ is the measure of angle $R$ ($2(18) + 11 = 47°$), which results from stopping after finding $x$ and reporting the wrong angle. The answer $50°$ is the measure of angle $S$ ($3(18) - 4 = 50°$), the same type of error. The answer $97°$ gives the exterior angle at $T$ instead of the interior angle, misreading what the question asks.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SIZ5KO', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'mcq', E'A theater sells adult tickets for 19 dollars each and child tickets for 11 dollars each. On a certain night, the theater sold 47 tickets and collected 685 dollars total. How many adult tickets were sold?', NULL, $lyceon_json$[{"key":"A","text":"$16$"},{"key":"B","text":"$19$"},{"key":"C","text":"$21$"},{"key":"D","text":"$26$"}]$lyceon_json$::jsonb, 'C', NULL, E'Let $a$ represent adult tickets and $c$ represent child tickets. The system is $a + c = 47$ and $19a + 11c = 685$. From the first equation, $c = 47 - a$. Substituting into the second: $19a + 11(47 - a) = 685$, giving $19a + 517 - 11a = 685$, so $8a = 168$ and $a = 21$. Then $c = 47 - 21 = 26$. Verification: $21 \\times 19 + 26 \\times 11 = 399 + 286 = 685$. The value $16$ results from an arithmetic error when dividing $168$ by $8$. The value $19$ comes from confusing the ticket price with the count of tickets. The value $26$ is the number of child tickets, not adult tickets.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SLB1B1', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'mcq', E'A student earns 17 dollars per hour tutoring and 13 dollars per hour at a bookstore. The student must earn more than 391 dollars per week but can work no more than 29 hours total. If $t$ represents tutoring hours and $b$ represents bookstore hours, which system of inequalities models this situation?', NULL, $lyceon_json$[{"key":"A","text":"$17t + 13b > 391$, $t + b \\leq 29$"},{"key":"B","text":"$17t + 13b \\geq 391$, $t + b < 29$"},{"key":"C","text":"$13t + 17b > 391$, $t + b \\leq 29$"},{"key":"D","text":"$17t + 13b > 391$, $t + b \\geq 29$"}]$lyceon_json$::jsonb, 'A', NULL, E'Tutoring pays 17 dollars per hour and bookstore pays 13 dollars per hour, so total earnings are $17t + 13b$. The student must earn more than 391 dollars, giving the strict inequality $17t + 13b > 391$. The student can work no more than 29 hours total, so $t + b \\leq 29$. The system $17t + 13b \\geq 391$ with $t + b < 29$ uses the wrong inequality types: it includes earning exactly 391 (the problem says more than) and excludes working exactly 29 hours (the problem allows up to 29). The system $13t + 17b > 391$ swaps the pay rates for the two jobs. The system with $t + b \\geq 29$ requires working at least 29 hours instead of at most 29.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TCCQIL', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'The function $f$ is defined by $f(x) = a \\cdot b^x$, where $a$ and $b$ are positive constants. If $f(2) = 18$ and $f(5) = 486$, what is the value of $f(0)$?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$6$"},{"key":"C","text":"$2$"},{"key":"D","text":"$\\frac{1}{3}$"}]$lyceon_json$::jsonb, 'C', NULL, E'Since $f(x) = a \\cdot b^x$, we have $a \\cdot b^2 = 18$ and $a \\cdot b^5 = 486$. Dividing the second equation by the first: $b^3 = \\frac{486}{18} = 27$, so $b = 3$. Substituting back: $a \\cdot 9 = 18$, giving $a = 2$. Therefore $f(0) = a \\cdot b^0 = a = 2$. The value $3$ confuses $b$ with $a$; it is the base, not the leading coefficient. The value $6$ comes from computing $a \\cdot b = 2 \\cdot 3$ instead of $a \\cdot b^0$. The value $\\frac{1}{3}$ results from an incorrect setup that inverts the ratio.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2U27I7O', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'grid_in', E'A teacher records the following quiz scores for $9$ students: $62, 71, 74, 78, 83, 83, 89, 91, 97$. The teacher adds one more student''s score, and the mean of all $10$ scores increases to $81$. What is the score of the $10$th student?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '82', ARRAY['82'], E'The sum of the original $9$ scores is $62 + 71 + 74 + 78 + 83 + 83 + 89 + 91 + 97 = 728$. For the mean of $10$ scores to be $81$, the total sum must be $81 \\times 10 = 810$. The $10$th student''s score is $810 - 728 = 82$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UAVIRM', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'mcq', E'A cone has a radius of $9$ cm and a slant height of $15$ cm. What is the volume of the cone?', NULL, $lyceon_json$[{"key":"A","text":"$324\\pi$ cubic cm"},{"key":"B","text":"$405\\pi$ cubic cm"},{"key":"C","text":"$675\\pi$ cubic cm"},{"key":"D","text":"$972\\pi$ cubic cm"}]$lyceon_json$::jsonb, 'A', NULL, E'First find the height using the Pythagorean theorem with the radius and slant height: $h = \\sqrt{15^2 - 9^2} = \\sqrt{225 - 81} = \\sqrt{144} = 12$ cm. The volume of a cone is $\\frac{1}{3}\\pi r^2 h = \\frac{1}{3}\\pi(81)(12) = 324\\pi$ cubic cm. The answer $405\\pi$ results from using the slant height ($15$) instead of the actual height ($12$) in the formula: $\\frac{1}{3}\\pi(81)(15) = 405\\pi$. The answer $675\\pi$ comes from using the slant height as the radius and the radius as the height: $\\frac{1}{3}\\pi(225)(9) = 675\\pi$. The answer $972\\pi$ comes from omitting the $\\frac{1}{3}$ factor: $\\pi(81)(12) = 972\\pi$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UCVXCS', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A random sample of $250$ residents in a city found that $62\\%$ support building a new library. The margin of error is $4\\%$. Which of the following is the most accurate interpretation of these results?', NULL, $lyceon_json$[{"key":"A","text":"Between $58\\%$ and $66\\%$ of all residents plausibly support the new library."},{"key":"B","text":"Between $62\\%$ and $66\\%$ of all residents plausibly support the new library."},{"key":"C","text":"Between $54\\%$ and $70\\%$ of all residents plausibly support the new library."},{"key":"D","text":"Between $60\\%$ and $64\\%$ of all residents plausibly support the new library."}]$lyceon_json$::jsonb, 'A', NULL, E'The confidence interval is the sample statistic plus or minus the margin of error: $62\\% \\pm 4\\%$, which gives $58\\%$ to $66\\%$. The range $62\\%$ to $66\\%$ only adds the margin of error above the estimate and ignores the lower bound. The range $54\\%$ to $70\\%$ doubles the margin of error in each direction ($62\\% \\pm 8\\%$). The range $60\\%$ to $64\\%$ uses a margin of error of $2\\%$ instead of the stated $4\\%$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2V3LS5I', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following expressions is equivalent to $7(3x - 11) + 4x$?', NULL, $lyceon_json$[{"key":"A","text":"$21x - 77$"},{"key":"B","text":"$25x - 11$"},{"key":"C","text":"$25x - 77$"},{"key":"D","text":"$25x + 77$"}]$lyceon_json$::jsonb, 'C', NULL, E'Distributing $7$ across $(3x - 11)$ gives $21x - 77$. Adding the remaining $4x$ yields $21x + 4x - 77 = 25x - 77$. The expression $21x - 77$ results from omitting the $+4x$ term entirely. The expression $25x - 11$ comes from failing to multiply $7 \\times 11$, keeping $-11$ unchanged. The expression $25x + 77$ introduces a sign error by treating $7(-11)$ as $+77$ instead of $-77$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2W45NM4', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'In triangle $PQR$, angle $P$ measures $37°$ and angle $Q$ measures $84°$. What is the measure, in degrees, of angle $R$?', NULL, $lyceon_json$[{"key":"A","text":"$49°$"},{"key":"B","text":"$59°$"},{"key":"C","text":"$69°$"},{"key":"D","text":"$121°$"}]$lyceon_json$::jsonb, 'B', NULL, E'The sum of the interior angles of a triangle is $180°$. So angle $R = 180° - 37° - 84° = 59°$. The answer $49°$ results from a subtraction error ($180 - 37 - 84 = 49$). The answer $69°$ results from a different subtraction error. The answer $121°$ comes from computing the supplement of the correct answer ($180° - 59°$), which confuses supplementary angles with the triangle angle sum.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
