INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WGA114', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'A researcher collects data on hours of sunlight per day ($x$) and plant growth in centimeters ($y$) over several weeks. The line of best fit is $y = 0.47x + 1.9$. One data point has $x = 13$ and an actual $y$-value of $9.2$. What is the residual for this data point?', NULL, $lyceon_json$[{"key":"A","text":"$1.19$"},{"key":"B","text":"$-1.19$"},{"key":"C","text":"$8.01$"},{"key":"D","text":"$0.81$"}]$lyceon_json$::jsonb, 'A', NULL, E'The predicted value is $y = 0.47(13) + 1.9 = 6.11 + 1.9 = 8.01$. The residual is actual minus predicted: $9.2 - 8.01 = 1.19$. The value $-1.19$ reverses the subtraction order (predicted minus actual) instead of actual minus predicted. The value $8.01$ is the predicted value itself, not the residual. The value $0.81$ results from an arithmetic error in computing $0.47 \\times 13$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WGYPFW', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A bag contains $9$ red marbles, $5$ blue marbles, and $6$ green marbles. If one marble is selected at random, what is the probability that it is blue?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{1}{4}$"},{"key":"B","text":"$\\frac{5}{14}$"},{"key":"C","text":"$\\frac{1}{5}$"},{"key":"D","text":"$\\frac{5}{9}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The total number of marbles in the bag is 9 + 5 + 6 = 20. The probability of selecting a blue marble is the number of blue marbles divided by the total, which is 5/20 = 1/4. The fraction 5/14 results from incorrectly using only the red and green marbles in the denominator. The fraction 1/5 results from dividing by the number of blue marbles rather than the total. The fraction 5/9 results from dividing by only the number of red marbles.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YDT1ZZ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'mcq', E'A data set contains the values $11, 14, 14, 17, 19, 23, 29$. What is the median of this data set?', NULL, $lyceon_json$[{"key":"A","text":"$17$"},{"key":"B","text":"$14$"},{"key":"C","text":"$18.14$"},{"key":"D","text":"$19$"}]$lyceon_json$::jsonb, 'A', NULL, E'The data set has $7$ values listed in order. The median is the middle (4th) value, which is $17$. The value $14$ is the mode (most frequent value), not the median. The value $18.14$ is approximately the mean ($\\frac{127}{7} \\approx 18.14$), confusing mean with median. The value $19$ is the 5th value, resulting from miscounting the middle position.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YQOR8U', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A cyclist travels $37$ miles in $2$ hours and $30$ minutes. A runner covers $19$ miles in $3$ hours and $10$ minutes. How many more miles per hour does the cyclist travel than the runner, rounded to the nearest tenth?', NULL, $lyceon_json$[{"key":"A","text":"$8.8$"},{"key":"B","text":"$6.0$"},{"key":"C","text":"$7.2$"},{"key":"D","text":"$9.6$"}]$lyceon_json$::jsonb, 'A', NULL, E'The cyclist''s rate is $\\frac{37}{2.5} = 14.8$ mph. The runner''s rate is $\\frac{19}{\\frac{19}{6}} = 6.0$ mph (since $3$ hours $10$ minutes $= \\frac{19}{6}$ hours). The difference is $14.8 - 6.0 = 8.8$ mph. The value $6.0$ is the runner''s speed alone, not the difference between the two speeds. The value $7.2$ comes from a computation error when dividing. The value $9.6$ results from incorrectly converting $30$ minutes to $0.3$ hours, computing the cyclist''s speed as $\\frac{37}{2.3} \\approx 16.1$ and subtracting $6.0$ to get about $9.6$ (after rounding artifacts).', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"unit_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Z0COKB', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'mcq', E'A researcher records the temperature of a chemical solution every minute. At $t = 0$ minutes, the temperature is 89 degrees Fahrenheit. The temperature decreases at a constant rate and reaches 47 degrees Fahrenheit at $t = 14$ minutes. At what time, in minutes, will the temperature first reach 26 degrees Fahrenheit?', NULL, $lyceon_json$[{"key":"A","text":"$21$"},{"key":"B","text":"$14$"},{"key":"C","text":"$7$"},{"key":"D","text":"$63$"}]$lyceon_json$::jsonb, 'A', NULL, E'The rate of change is $\\frac{47 - 89}{14 - 0} = \\frac{-42}{14} = -3$ degrees per minute. The linear function is $f(t) = -3t + 89$. Setting $f(t) = 26$: $-3t + 89 = 26$, so $-3t = -63$ and $t = 21$. The value $14$ is the time when the temperature reaches 47 degrees, not 26 degrees. The value $7$ results from computing the additional time past $t = 14$ for the temperature to drop from 47 to 26 degrees but neglecting to add 14 to get the total time. The value $63$ comes from computing $89 - 26 = 63$ without dividing by the rate of 3 degrees per minute.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZWKXBT', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'mcq', E'In a survey of $1{,}200$ residents, $35\\%$ preferred option X and $25\\%$ preferred option Y. Of those who preferred option X, $40\\%$ also expressed interest in option Z. Of those who preferred option Y, $60\\%$ also expressed interest in option Z. What percentage of all $1{,}200$ surveyed residents expressed interest in option Z? (Assume only those who preferred X or Y could express interest in Z.)', NULL, $lyceon_json$[{"key":"A","text":"$29\\%$"},{"key":"B","text":"$50\\%$"},{"key":"C","text":"$24\\%$"},{"key":"D","text":"$36\\%$"}]$lyceon_json$::jsonb, 'A', NULL, E'Those preferring X: $1{,}200 \\times 0.35 = 420$. Of those, $40\\%$ expressed interest in Z: $420 \\times 0.40 = 168$. Those preferring Y: $1{,}200 \\times 0.25 = 300$. Of those, $60\\%$ expressed interest in Z: $300 \\times 0.60 = 180$. Total interested in Z: $168 + 180 = 348$. Percentage: $\\frac{348}{1{,}200} \\times 100 = 29\\%$. The value $50\\%$ comes from averaging $40\\%$ and $60\\%$ without weighting by group size. The value $24\\%$ results from applying only the $40\\%$ rate to the combined X-and-Y group of $720$. The value $36\\%$ comes from incorrectly weighting the percentages using the wrong group proportions.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW210FOJK', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Economist Lucia Ferreira has demonstrated that microfinance programs in rural Guatemala increased household incomes by an average of 23 percent over a five-year period. Her analysis also revealed, however, that loan repayment rates declined sharply after the third year, with nearly 41 percent of borrowers defaulting by year five. ______ Ferreira cautions that the long-term sustainability of such programs depends not merely on initial income gains but on the development of local financial literacy initiatives that help borrowers manage debt obligations over time.', $lyceon_json$[{"key":"A","text":"Furthermore,"},{"key":"B","text":"In other words,"},{"key":"C","text":"For this reason,"},{"key":"D","text":"Regardless,"}]$lyceon_json$::jsonb, 'C', NULL, E'The preceding sentences establish a tension: microfinance boosted incomes but also produced high default rates. The sentence after the blank presents Ferreira''s caution as a conclusion drawn from this tension. "For this reason," correctly signals that the high default rates are the cause of her cautionary recommendation. "Furthermore," merely adds another point without capturing the causal relationship between the default data and the recommendation. "In other words," implies the sentence restates the default finding, but Ferreira''s caution introduces a new prescriptive claim about financial literacy. "Regardless," suggests the caution applies irrespective of the preceding evidence, when in fact the caution is directly motivated by it.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW220D95R', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'Researchers at the University of Helsinki recently completed a seven-year study tracking the foraging patterns of Eurasian jays in fragmented boreal forests. The team fitted 143 birds with lightweight GPS transmitters and recorded over 2.6 million location points. Their findings indicate that jays in highly fragmented landscapes travel, on average, 37 percent farther per day than jays in continuous forest to acquire comparable quantities of food. The additional energy expenditure, the researchers note, may reduce overwinter survival rates by as much as 11 percent, underscoring the hidden metabolic costs that habitat fragmentation imposes on scatter-hoarding species.', $lyceon_json$[{"key":"A","text":"Habitat fragmentation forces Eurasian jays to travel significantly farther for food, which may lower their survival rates."},{"key":"B","text":"GPS transmitter technology has enabled researchers to collect unprecedented amounts of data on bird movement patterns."},{"key":"C","text":"Eurasian jays are better adapted to continuous forests than to fragmented landscapes because they cache food in scattered locations."},{"key":"D","text":"A seven-year study in Finland found that boreal forests are declining at a faster rate than scientists had previously estimated."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage centers on the finding that jays in fragmented forests must travel 37 percent farther for food and that this extra energy expenditure may reduce their overwinter survival. The choice stating that habitat fragmentation forces jays to travel farther and may lower survival rates captures this central point. The choice about GPS technology describes only the study''s methodology, not its central finding. The choice about jays being better adapted to continuous forests introduces a comparative claim the passage never makes. The choice about boreal forest decline rates misrepresents the study''s subject entirely, since the passage discusses jay foraging costs, not deforestation rates.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW221HUGB', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'Historian Adela Pineiro argues that the so-called Golden Age of the empire was in fact a period of significant internal decay. While the court projected an image of prosperity, provincial administrators were systematically ________ public funds, leaving rural infrastructure to deteriorate beyond repair.', $lyceon_json$[{"key":"A","text":"siphoning"},{"key":"B","text":"auditing"},{"key":"C","text":"distributing"},{"key":"D","text":"soliciting"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage presents a contrast between an outward image of prosperity and actual internal decay, with administrators causing rural infrastructure to deteriorate. "Siphoning" means to illicitly divert or drain resources, which explains both the financial mismanagement and the resulting infrastructure collapse. "Auditing" means to examine accounts officially, which would be a corrective action rather than a cause of decay. "Distributing" means to allocate or hand out, which implies a legitimate administrative function and does not explain why infrastructure was left to deteriorate. "Soliciting" means to seek or request something, which does not describe the act of taking funds away from their intended purpose.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW227IEOB', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Linguist Marjorie Okeke has documented how the Ibibio language of southeastern Nigeria preserves tonal distinctions that many neighboring languages have _______ analysis of recorded speech from 43 villages shows that speakers over the age of sixty maintain an average of nine distinct tonal contours, while speakers under thirty use only five.', $lyceon_json$[{"key":"A","text":"lost. Her"},{"key":"B","text":"lost, her"},{"key":"C","text":"lost her"},{"key":"D","text":"lost: her"}]$lyceon_json$::jsonb, 'A', NULL, E'The text contains two independent clauses: the first describes how the Ibibio language preserves tonal distinctions that neighboring languages have lost, and the second presents Okeke''s analysis of recorded speech from 43 villages. A period after ''lost'' correctly separates these two complete thoughts into distinct sentences, with ''Her'' properly capitalized to begin the new sentence. Using a comma after ''lost'' creates a comma splice, improperly joining two independent clauses with only a comma. Removing all punctuation after ''lost'' produces a run-on sentence that fuses two independent clauses without any separation. A colon after ''lost'' is incorrect because the second clause does not define, explain, or elaborate on the word ''lost''; instead it introduces an entirely separate point about Okeke''s speech analysis, which is not the kind of relationship a colon signals.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW22VI8R5', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'A marine biologist hypothesizes that deep-sea bioluminescent organisms use distinct flash patterns primarily to coordinate schooling behavior rather than to attract prey. Which finding, if true, would most directly weaken this hypothesis?', E'Many deep-sea fish and invertebrates produce light through chemical reactions involving the enzyme luciferase. Scientists have long debated the primary function of bioluminescence in these organisms. Proposed functions include attracting prey, deterring predators through startle displays, facilitating mate recognition, and coordinating group movement in lightless environments. Recent advances in submersible camera technology have enabled researchers to observe bioluminescent behaviors in situ at depths exceeding 3,000 meters for the first time.', $lyceon_json$[{"key":"A","text":"High-speed video analysis reveals that 89 percent of observed flash sequences in the anglerfish Cryptopsaras couesii occur when the fish is solitary and stationary, ceasing immediately when small crustaceans approach the lure."},{"key":"B","text":"Laboratory experiments show that certain bioluminescent jellyfish increase their flash rate when exposed to simulated predator shadows."},{"key":"C","text":"Genetic sequencing indicates that the luciferase gene evolved independently at least 47 times across marine lineages."},{"key":"D","text":"Population surveys find that bioluminescent species are more abundant in the mesopelagic zone than in the bathypelagic zone."}]$lyceon_json$::jsonb, 'A', NULL, E'The hypothesis claims that bioluminescent flashing serves primarily to coordinate schooling. The finding that 89 percent of flash sequences occur when anglerfish are solitary and stationary -- and stop when prey approach the lure -- directly weakens this claim by showing the dominant use is solitary and prey-related, not group coordination. The finding about jellyfish increasing flash rates near predator shadows addresses predator deterrence in a different taxon and does not address schooling coordination. The finding about independent evolution of luciferase concerns evolutionary history rather than the behavioral function of flashing. The finding about species abundance across depth zones describes distribution patterns without bearing on whether flashing coordinates schooling.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW23DOHDD', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'Researchers at the University of Helsinki recently identified a previously unknown species of parasitic wasp in the cloud forests of Ecuador. The species, named Capitonius obscurus, lays its eggs inside the larvae of bark beetles. ______ the discovery has prompted entomologists to revisit collections of preserved insect specimens from the same region, hoping to determine whether the species had been misidentified in earlier surveys.', $lyceon_json$[{"key":"A","text":"Consequently,"},{"key":"B","text":"In contrast,"},{"key":"C","text":"Meanwhile,"},{"key":"D","text":"Nevertheless,"}]$lyceon_json$::jsonb, 'A', NULL, E'The second sentence describes a new discovery, and the sentence after the blank describes a direct result of that discovery: entomologists revisiting collections. "Consequently," correctly signals a cause-and-effect relationship. "In contrast," wrongly implies a contradiction between the discovery and the revisiting of collections. "Meanwhile," suggests two simultaneous but unrelated events, which misrepresents the causal link. "Nevertheless," implies the revisiting happened despite the discovery, introducing an unwarranted concession.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW251Z29F', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'Which choice best states the main idea of the text?', E'In 1928, the Indian physicist C. V. Raman demonstrated that when monochromatic light passes through a transparent substance, a small fraction of the scattered light emerges at wavelengths different from the incident beam. This phenomenon, now called the Raman effect, occurs because photons exchange energy with molecular vibrations, shifting to either higher or lower frequencies. Although the effect is extremely weak -- typically only one in ten million photons is Raman-scattered -- modern laser sources and sensitive detectors have turned Raman spectroscopy into a workhorse analytical technique. Today it is used to identify pharmaceutical compounds, authenticate gemstones, detect explosives at airport checkpoints, and even analyze the pigments in centuries-old paintings without damaging them.', $lyceon_json$[{"key":"A","text":"An obscure quantum phenomenon discovered in the early twentieth century has become the basis for a versatile and widely applied analytical technique."},{"key":"B","text":"C. V. Raman's discovery of inelastic light scattering earned him immediate recognition but had no practical applications until laser technology matured decades later."},{"key":"C","text":"Raman spectroscopy is superior to all other methods of chemical analysis because it can identify substances without physical contact."},{"key":"D","text":"The weakness of the Raman effect has limited its usefulness primarily to high-budget research laboratories with specialized equipment."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage traces the Raman effect from its 1928 discovery through its development into a widely used analytical tool, making the choice about an obscure phenomenon becoming a versatile technique the best summary of the central idea. The choice claiming Raman received immediate recognition and that the technique had no applications until lasers arrived overstates what the passage says -- the text never discusses Raman''s recognition or claims there were zero earlier uses. The choice asserting superiority over all other methods introduces a superlative comparison absent from the passage. The choice about limited usefulness directly contradicts the passage''s emphasis on the technique''s broad modern applications.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2828Q2G', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 2, 'mcq', E'Which choice best describes a difference in how the two texts characterize the role of wetlands?', E'Text 1: Ecologist Haruto Nishida maintains that coastal wetlands function primarily as carbon sinks, sequestering atmospheric carbon dioxide in their soils at rates up to fifty times greater per unit area than tropical forests. Nishida''s 2020 study of mangrove sediments along the Philippine coastline measured carbon storage densities exceeding 1,100 tonnes per hectare in soils over three meters deep.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW29GO1FQ', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Neither the laboratory director nor the two postdoctoral researchers _______ able to replicate the anomalous readings that appeared during the September 2023 trial of the superconducting magnet array, leading the team to suspect an instrumentation fault rather than a genuine physical phenomenon.', $lyceon_json$[{"key":"A","text":"was"},{"key":"B","text":"were"},{"key":"C","text":"is"},{"key":"D","text":"has been"}]$lyceon_json$::jsonb, 'B', NULL, E'In a ''neither...nor'' construction, the verb agrees with the subject closest to it. Here, ''the two postdoctoral researchers'' is the nearer subject and is plural, so the plural past-tense form ''were'' is required. The singular past-tense form ''was'' incorrectly treats the subject as singular, ignoring the proximity rule that governs ''neither...nor'' constructions. The singular present-tense form ''is'' commits both a number error (singular instead of plural) and a tense error, since the September 2023 trial clearly places the action in the past. The singular present-perfect form ''has been'' also fails on number agreement with the plural nearer subject and introduces an inappropriate tense shift.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2AG0Y0G', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'Although the neighboring provinces had long maintained separate trade agreements with foreign merchants, the newly appointed governor sought to ________ these arrangements into a single unified code that would apply uniformly across the region.', $lyceon_json$[{"key":"A","text":"consolidate"},{"key":"B","text":"commemorate"},{"key":"C","text":"disguise"},{"key":"D","text":"postpone"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes a governor who wants to bring multiple separate trade agreements together into one unified code. "Consolidate" means to combine several things into a single, more effective whole, which directly matches this goal. "Commemorate" means to honor or remember a past event, which has nothing to do with unifying trade arrangements. "Disguise" means to conceal the true nature of something, which contradicts the straightforward administrative action described. "Postpone" means to delay to a later time, which does not address combining separate agreements into one.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2AX9WWW', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Every spring, the municipal gardens in Brno, Czech Republic, _______ a horticultural exhibition that attracts visitors from across Central Europe. The event showcases over 200 species of flowering plants cultivated by local botanists.', $lyceon_json$[{"key":"A","text":"hosts"},{"key":"B","text":"host"},{"key":"C","text":"hosting"},{"key":"D","text":"to host"}]$lyceon_json$::jsonb, 'B', NULL, E'The subject of the sentence is ''the municipal gardens,'' which is plural. The sentence describes a recurring event (''Every spring''), requiring a present-tense verb that agrees with the plural subject. The plural present-tense form ''host'' correctly agrees with ''gardens.'' The singular form ''hosts'' fails to agree with the plural subject ''gardens.'' The participial form ''hosting'' cannot serve as the main verb without an auxiliary, creating a sentence fragment. The infinitive ''to host'' also cannot function as the main verb of the sentence, leaving the clause without a finite verb.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2BZPDOZ', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'During the late nineteenth century, the Chilean government financed the construction of an extensive railway network connecting the nitrate mining regions of the Atacama Desert to Pacific coastal ports. The railways drastically reduced the cost of transporting sodium nitrate, which was then the world''s most important agricultural fertilizer, to international markets. By the 1920s, however, German chemist Fritz Haber''s process for synthesizing ammonia from atmospheric nitrogen had enabled the industrial production of synthetic fertilizers at a fraction of the cost of natural nitrate. As synthetic fertilizers captured an ever-larger share of the global market, the economic rationale for maintaining the Atacama rail network ________', $lyceon_json$[{"key":"A","text":"eroded, since the mines that the railways had been built to serve were losing their primary customer base to a cheaper substitute product."},{"key":"B","text":"strengthened, because the railways could easily be repurposed to transport synthetic fertilizers manufactured in coastal factories."},{"key":"C","text":"remained unchanged, as Chilean nitrate continued to dominate global fertilizer markets throughout the twentieth century."},{"key":"D","text":"shifted from commercial freight to passenger service as urban populations in the Atacama region expanded rapidly."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage establishes that the railways existed to transport natural nitrate from mines to ports, and that synthetic fertilizers undercut the market for natural nitrate. The logical inference is that as demand for natural nitrate fell, the economic justification for maintaining railways built specifically to serve those mines would erode. The choice about repurposing railways for synthetic fertilizer transport introduces an unsupported scenario the passage gives no basis for -- synthetic fertilizers are described as produced industrially, not in coastal Chilean factories. The choice about continued dominance of Chilean nitrate directly contradicts the passage''s statement that synthetic fertilizers were capturing an ever-larger market share. The choice about passenger service and urban expansion introduces facts about population growth that the passage neither states nor implies.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2CW5WFX', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The eighteenth-century naturalist Maria Sibylla Merian, whose meticulous illustrations of Surinamese insects _______ among the earliest European documentation of tropical metamorphosis, challenged prevailing theories by demonstrating that butterflies emerge from caterpillars rather than arising spontaneously from mud.', $lyceon_json$[{"key":"A","text":"ranks"},{"key":"B","text":"rank"},{"key":"C","text":"ranking"},{"key":"D","text":"has ranked"}]$lyceon_json$::jsonb, 'B', NULL, E'The nonrestrictive relative clause ''whose meticulous illustrations of Surinamese insects _______ among the earliest European documentation'' has ''illustrations'' as its subject, which is plural. The plural present-tense form ''rank'' correctly agrees with the plural subject. The singular form ''ranks'' fails because it does not agree with the plural ''illustrations.'' The participial form ''ranking'' cannot serve as the finite verb of the relative clause, producing a fragment within the clause structure. The singular present-perfect form ''has ranked'' commits a number agreement error with the plural subject and also awkwardly implies that the illustrations performed the act of ranking themselves rather than simply holding a position among historical documents.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2DGYR8P', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'The ceramicist''s latest series of bowls featured walls so thin they were nearly translucent, demonstrating the artist''s remarkable ________ in manipulating the clay.', $lyceon_json$[{"key":"A","text":"finesse"},{"key":"B","text":"integrity"},{"key":"C","text":"stamina"},{"key":"D","text":"urgency"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes a ceramicist creating extremely thin, nearly translucent bowl walls, which indicates exceptional delicacy and skill. "Finesse" means refined skill or delicacy, fitting the context of precise clay manipulation. "Integrity" refers to moral wholeness or structural soundness, neither of which matches the idea of skillful manipulation. "Stamina" denotes physical endurance, which does not address the precision described. "Urgency" implies pressing importance or haste, which contradicts the careful, delicate work depicted.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2E1DH3Z', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'A student claims that the drought of 1934 caused more widespread agricultural damage across the United States than any other single-year drought in the twentieth century. Which finding, if true, would most directly support this claim?', E'Between 1930 and 1940, the Great Plains experienced a series of severe droughts that devastated agricultural output and displaced hundreds of thousands of farming families. The drought conditions were driven by a combination of below-average rainfall, high temperatures, and decades of aggressive plowing that had stripped the topsoil of its natural grass cover. Government meteorologists noted that 1934 and 1936 were the two most acute drought years during this period, though they differed considerably in geographic scope and intensity.', $lyceon_json$[{"key":"A","text":"USDA records show that in 1934, crop failures were reported in 75 percent of U.S. counties, a proportion unmatched by any other single-year drought before or after during the century."},{"key":"B","text":"Farmers in the southern Great Plains reported that dust storms in 1935 were more frequent and more damaging than those in any prior year."},{"key":"C","text":"The 1936 drought produced the highest recorded temperatures in eleven Midwestern states, breaking records that had stood since the 1890s."},{"key":"D","text":"Federal relief spending on drought assistance increased steadily throughout the 1930s, reaching its peak in 1938."}]$lyceon_json$::jsonb, 'A', NULL, E'The claim is specifically that the 1934 drought caused more widespread agricultural damage than any other single-year drought in the twentieth century. The finding about USDA records showing crop failures in 75 percent of counties in 1934, unmatched by any other single-year drought, directly supports both the year and the superlative scope of the claim. The finding about 1935 dust storms concerns a different year and addresses dust storms rather than drought-caused agricultural damage. The finding about 1936 temperatures supports the severity of 1936, not 1934, and addresses heat records rather than agricultural damage. The finding about peak relief spending in 1938 is about federal expenditure trends, not the geographic breadth of agricultural damage in any single drought year.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ED4RKW', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Computational chemist Yuki Taniguchi developed a novel algorithm for predicting molecular binding _______ which can simulate interactions between thousands of protein variants in under an hour, has already been adopted by three pharmaceutical companies seeking to accelerate their drug discovery pipelines.', $lyceon_json$[{"key":"A","text":"affinities. The algorithm,"},{"key":"B","text":"affinities, the algorithm,"},{"key":"C","text":"affinities the algorithm,"},{"key":"D","text":"affinities, the algorithm"}]$lyceon_json$::jsonb, 'A', NULL, E'Two independent clauses are present: the first states that Taniguchi developed a novel algorithm, and the second provides further detail about what the algorithm can do and who has adopted it. A period after ''affinities'' correctly ends the first sentence, and ''The algorithm,'' with a comma, properly introduces the nonrestrictive relative clause ''which can simulate interactions between thousands of protein variants in under an hour'' that is set off by paired commas. Using a comma after ''affinities'' followed by ''the algorithm,'' produces a comma splice joining two independent clauses. Omitting punctuation entirely after ''affinities'' creates a run-on sentence. Using a comma after ''affinities'' but omitting the comma after ''algorithm'' fails to properly open the nonrestrictive ''which'' clause and also creates the comma splice problem, resulting in a doubly flawed construction.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2GPY8VX', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'The fruit fly Drosophila melanogaster has been used in genetics research for over a century, in part because of its rapid generation time: a new generation can be produced every ten to twelve days under laboratory conditions. This speed allows researchers to observe the effects of genetic mutations across many generations in a relatively short period. By contrast, studying comparable multigenerational genetic effects in organisms with longer generation times, such as elephants, which have a gestation period of approximately 22 months, would ________', $lyceon_json$[{"key":"A","text":"require decades of observation, making such studies impractical for most research timelines."},{"key":"B","text":"yield more reliable data because larger organisms have more stable genomes."},{"key":"C","text":"be unnecessary because elephant genetics are already fully understood."},{"key":"D","text":"produce results identical to those obtained from Drosophila studies."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage establishes that Drosophila''s value lies in its rapid generation time, which enables multigenerational observation over short periods. The text then contrasts this with elephants'' 22-month gestation. The logical completion is that studying comparable multigenerational effects in elephants would require decades, making such research impractical. The choice about more reliable data from larger organisms introduces an unsupported claim about genome stability that the passage does not imply. The choice about elephant genetics being fully understood is contradicted by the passage''s framing, which discusses the difficulty of studying such organisms, not the completeness of existing knowledge. The choice about identical results ignores the passage''s emphasis on the practical differences between the two organisms.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2H6A2L6', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Marine biologist Anika Patel has spent over a decade studying the migratory patterns of leatherback sea turtles in the eastern Pacific. Her research has revealed that these turtles travel an average of 7,400 miles per _______ Patel''s team uses satellite tags to monitor the turtles'' routes in real time.', $lyceon_json$[{"key":"A","text":"year."},{"key":"B","text":"year"},{"key":"C","text":"year,"},{"key":"D","text":"year, but,"}]$lyceon_json$::jsonb, 'A', NULL, E'The text contains two independent clauses: the first states that turtles travel an average of 7,400 miles per year, and the second describes how Patel''s team uses satellite tags. A period after ''year'' correctly separates these two complete thoughts into distinct sentences. Omitting all punctuation after ''year'' creates a run-on sentence that fuses two independent clauses without any separation. Using only a comma after ''year'' produces a comma splice, improperly joining two independent clauses with just a comma. Placing commas both before and after ''but'' incorrectly treats ''but'' as a parenthetical element rather than a coordinating conjunction, and the contrast implied by ''but'' is not warranted by the content.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2H9SW6P', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the overall purpose of the text?', E'Literary scholar Renata Voss contends that the protagonist of Elara Jokinen''s 1953 novel The Silt Margin is often misread as a passive figure overwhelmed by circumstance. Voss points out that the protagonist''s repeated refusals to leave the deteriorating farmstead are not signs of helplessness but rather deliberate acts of resistance against the industrialization consuming the surrounding valley. By choosing to remain, the protagonist asserts a form of agency that, as Voss notes, earlier critics failed to recognize because they equated mobility with autonomy.', $lyceon_json$[{"key":"A","text":"To challenge an established interpretation of a literary character by proposing an alternative reading of the character's actions"},{"key":"B","text":"To compare two novels that address the theme of industrialization in contrasting ways"},{"key":"C","text":"To trace the evolution of a protagonist across multiple works by the same author"},{"key":"D","text":"To argue that literary critics should prioritize biographical context when analyzing fictional characters"}]$lyceon_json$::jsonb, 'A', NULL, E'The text presents Voss''s argument that the protagonist has been misread as passive and then offers a reinterpretation of the character''s actions as deliberate resistance, directly challenging earlier critical readings. The choice about comparing two novels is incorrect because only one novel is discussed. The choice about tracing a protagonist across multiple works is incorrect because the passage addresses a single novel and does not mention other works by Jokinen. The choice about prioritizing biographical context is incorrect because Voss''s argument centers on reinterpreting textual actions, not on applying the author''s biography to the analysis.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2IGWKFL', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The documentary chronicles the efforts of three siblings who, after inheriting a neglected vineyard in the Douro Valley, _______ to restore the terraced hillsides using only the agricultural methods their grandparents had practiced decades earlier.', $lyceon_json$[{"key":"A","text":"has endeavored"},{"key":"B","text":"endeavors"},{"key":"C","text":"endeavored"},{"key":"D","text":"was endeavoring"}]$lyceon_json$::jsonb, 'C', NULL, E'The relative clause beginning with ''who'' describes past events: the siblings inherited the vineyard and then took action. The past-tense form ''endeavored'' correctly matches the past time frame established by ''after inheriting'' and ''had practiced decades earlier,'' and it agrees in number with the plural antecedent ''siblings.'' The singular present perfect form ''has endeavored'' fails because the subject ''who'' refers to the plural ''siblings,'' creating a subject-verb agreement error. The present-tense form ''endeavors'' conflicts with the past time frame of the inherited vineyard narrative. The singular past progressive form ''was endeavoring'' does not agree with the plural antecedent ''siblings,'' which requires ''were endeavoring.''', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2K4TY6V', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'A political scientist argues that ranked-choice voting (RCV) reduces negative campaigning because candidates must appeal to opponents'' supporters for second-choice votes. Which finding, if true, would most directly undermine this argument?', E'Ranked-choice voting allows voters to rank candidates in order of preference. If no candidate receives a majority of first-choice votes, the candidate with the fewest first-choice votes is eliminated and that candidate''s ballots are redistributed according to the voters'' next preferences. This process continues until one candidate achieves a majority. Proponents argue that RCV encourages more civil campaigns, reduces strategic voting, and produces winners with broader coalitions of support. Critics counter that RCV introduces ballot complexity, increases rates of ballot exhaustion, and may not deliver the behavioral incentives its advocates claim.', $lyceon_json$[{"key":"A","text":"A study of 97 RCV elections in four U.S. cities finds that candidates' rates of personal attacks, as measured by independent ad-tracking databases, were statistically indistinguishable from rates in comparable plurality elections in matched cities during the same period."},{"key":"B","text":"Surveys conducted after RCV elections show that 62 percent of voters found the ranked ballot easy to complete."},{"key":"C","text":"In three of the four cities studied, voter turnout in RCV elections was 4 to 7 percentage points higher than in prior plurality elections."},{"key":"D","text":"Campaign finance records reveal that candidates in RCV elections spent an average of 14 percent less on advertising than candidates in plurality elections in the same jurisdictions."}]$lyceon_json$::jsonb, 'A', NULL, E'The argument is that RCV reduces negative campaigning. The finding that personal attack rates in 97 RCV elections were statistically indistinguishable from those in comparable plurality elections directly undermines this claim by showing no measurable reduction in negativity. The finding about voters finding ranked ballots easy to complete addresses ballot usability, not campaign tone. The finding about higher voter turnout concerns participation rates, which is a different dimension from campaign negativity. The finding about lower advertising spending addresses total expenditure, not the content or tone of campaigns.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2KS8P21', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'In her 2019 monograph, archaeologist Priya Vaidyanathan argued that the Indus Valley settlement at Dholavira functioned primarily as a regional trade hub, citing the unusually high concentration of standardized weights found at the site. Subsequent excavations by a team from the Archaeological Survey of India uncovered extensive water management infrastructure, including sixteen reservoirs connected by an intricate channel system. ______ Vaidyanathan has revised her thesis to describe Dholavira as a dual-purpose settlement that served both commercial and hydraulic-engineering functions.', $lyceon_json$[{"key":"A","text":"Similarly,"},{"key":"B","text":"In light of these findings,"},{"key":"C","text":"By contrast,"},{"key":"D","text":"Specifically,"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage describes how new excavation evidence (water infrastructure) led Vaidyanathan to revise her original thesis. "In light of these findings," correctly signals that the revision was prompted by the newly uncovered evidence. "Similarly," incorrectly implies the water infrastructure parallels the trade-hub thesis rather than expanding it. "By contrast," partially captures the shift in Vaidyanathan''s thinking but mischaracterizes the relationship, since the revision integrates the new evidence into a broader thesis rather than opposing the original claim. "Specifically," wrongly suggests the water infrastructure is a detail supporting the trade-hub argument rather than new evidence that changed the thesis.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2LOPJN6', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the underlined sentence in the overall structure of the text?', E'Coral reefs support roughly one quarter of all known marine species despite covering less than one percent of the ocean floor. Marine biologist Tomoko Hara has documented that reefs in the Coral Triangle region harbor over 600 species of hard coral alone. <u>Hara emphasizes that the extraordinary biodiversity of these ecosystems makes them critical subjects for conservation research.</u>', $lyceon_json$[{"key":"A","text":"It states a conclusion drawn from the information presented earlier in the text."},{"key":"B","text":"It introduces a finding that contradicts a widely held assumption about coral reefs."},{"key":"C","text":"It provides a specific example to illustrate a general claim about marine ecosystems."},{"key":"D","text":"It raises a question about the methodology used in coral reef surveys."}]$lyceon_json$::jsonb, 'A', NULL, E'The underlined sentence states that coral reef biodiversity makes these ecosystems critical for conservation research, which serves as a concluding inference drawn from the preceding facts about reef biodiversity and species counts. The claim that the sentence introduces a contradictory finding is incorrect because the underlined sentence reinforces rather than challenges the preceding information. The suggestion that it provides a specific example is inaccurate because the sentence offers a broad evaluative statement, not a concrete instance. The idea that it raises a question about methodology is unsupported, as no methodological inquiry appears in the sentence.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2MZ0ZY8', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 3, 'mcq', E'Based on the texts, how would the author of Text 1 most likely respond to the argument presented in Text 2?', E'Text 1: Linguist Daphne Reymond argues that the rapid adoption of loanwords from dominant global languages does not signal the decline of minority languages but rather demonstrates their vitality. In her 2022 analysis of Breton spoken in western France, Reymond found that speakers who incorporated the most French and English loanwords also exhibited the highest rates of Breton neologism creation, suggesting that lexical borrowing and linguistic innovation operate in tandem rather than in opposition.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NN4052', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'In 1987, archaeologist Tomás Herrera unearthed a collection of ceramic vessels near the Peruvian highlands. The vessels, which date to approximately 1350 _______ distinctive geometric patterns that scholars believe served both decorative and ritualistic purposes.', $lyceon_json$[{"key":"A","text":"CE, feature"},{"key":"B","text":"CE feature"},{"key":"C","text":"CE. They feature"},{"key":"D","text":"CE— feature"}]$lyceon_json$::jsonb, 'A', NULL, E'The phrase ''which date to approximately 1350 CE'' is a nonrestrictive relative clause set off by commas. The opening comma appears before ''which,'' so a closing comma must follow ''CE'' to complete the pair before the main clause resumes with ''feature.'' Omitting the comma after ''CE'' fails to close the nonrestrictive clause, creating a structural error. Placing a period after ''CE'' and starting a new sentence with ''They feature'' severs the relative clause from the main clause it modifies; the main verb ''feature'' belongs to the original sentence''s subject ''The vessels,'' and splitting it off produces an incomplete first sentence. Using an em dash after ''CE'' without a closing em dash fails to properly bracket the nonrestrictive clause and introduces an abrupt, unconventional break in the sentence.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NNSUDJ', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 1, 'mcq', E'Based on the texts, how would the author of Text 2 most likely respond to the claim made in Text 1?', E'Text 1: Nutritionist Pavel Ostrenko argues that fortifying staple grains with micronutrients is the most cost-effective strategy for reducing nutritional deficiencies in low-income populations. He cites data from a 2019 study showing that iron-fortified wheat flour reduced anemia rates by 37 percent in a Central Asian trial population.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Q6WPD8', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best states the main idea of the text?', E'Conventional accounts of the Harlem Renaissance emphasize its literary and musical achievements while treating the visual arts as secondary. Art historian Bridget R. Cooks challenges this narrative, arguing that painters such as Aaron Douglas and sculptors such as Augusta Savage were not merely illustrating ideas generated by writers but were independently theorizing Black modernity through form and material. Douglas''s layered silhouettes, for instance, drew on Egyptian wall painting and Art Deco geometry to propose a visual genealogy linking African diasporic peoples across centuries -- a historiographic argument that had no direct parallel in the contemporaneous poetry of Langston Hughes or Claude McKay. By foregrounding the conceptual autonomy of these visual artists, Cooks contends, scholars can recover a dimension of the Renaissance that literary-centered histories have systematically obscured.', $lyceon_json$[{"key":"A","text":"Bridget R. Cooks argues that Harlem Renaissance visual artists were independent theorists of Black modernity whose contributions have been undervalued by literary-focused histories."},{"key":"B","text":"Aaron Douglas's use of Egyptian and Art Deco visual elements was more innovative than the literary techniques employed by Langston Hughes and Claude McKay."},{"key":"C","text":"The Harlem Renaissance is best understood as a movement in which writers and visual artists collaborated closely to advance a shared political agenda."},{"key":"D","text":"Art historians have recently discovered previously unknown paintings by Augusta Savage that fundamentally alter scholarly understanding of the Harlem Renaissance."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage presents Cooks''s argument that Harlem Renaissance visual artists independently theorized Black modernity and that literary-centered accounts have obscured their conceptual contributions. The choice capturing Cooks''s claim about visual artists as independent theorists whose work has been undervalued reflects this central idea. The choice about Douglas being more innovative than Hughes and McKay introduces a qualitative ranking the passage does not make; the text notes Douglas''s work had no direct parallel in their poetry, but it does not claim superiority. The choice about close collaboration contradicts the passage''s emphasis on the conceptual autonomy of visual artists from writers. The choice about recently discovered paintings fabricates an event the passage never mentions.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2SEP9CW', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'In 1987, geochemist Miriam Kastner proposed that methane hydrates beneath the seafloor could contain more carbon than all known fossil fuel reserves combined. Subsequent drilling expeditions in the Gulf of Mexico and the Sea of Japan confirmed the presence of vast hydrate deposits, though estimates of their total volume varied by orders of magnitude. More recently, climate scientists have warned that rising ocean temperatures could destabilize these deposits, potentially releasing enormous quantities of methane into the atmosphere and accelerating global warming.', $lyceon_json$[{"key":"A","text":"It presents a scientific claim, describes evidence that supported the claim with some qualification, and then discusses an implication of the phenomenon."},{"key":"B","text":"It contrasts two competing hypotheses about methane hydrates and then resolves the debate by citing recent experimental findings."},{"key":"C","text":"It describes a technological innovation, explains how the innovation was tested in multiple locations, and then evaluates its commercial viability."},{"key":"D","text":"It introduces a researcher's biography, summarizes the researcher's major publications, and then assesses the researcher's influence on the field."}]$lyceon_json$::jsonb, 'A', NULL, E'The text first introduces Kastner''s claim about the carbon content of methane hydrates, then describes drilling expeditions that confirmed the deposits while noting uncertainty in volume estimates, and finally discusses the climate implications of destabilization. The choice describing two competing hypotheses resolved by experiment is incorrect because the text presents one claim that is supported, not a debate between rivals. The choice about a technological innovation and commercial viability mischaracterizes the passage, which discusses a natural geological phenomenon and environmental risk rather than a technology or its market potential. The choice about a researcher''s biography and publications is incorrect because the text mentions Kastner only to attribute the initial claim and does not discuss her career or body of work.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2UIU9OJ', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Neuroscientist Maria Velasco and her team studied how bilingual speakers of Basque and Spanish process grammatically gendered nouns. In Spanish, the word for "bridge" (puente) is masculine, while in Basque, nouns carry no grammatical gender. Velasco found that when bilingual participants were asked to describe bridges in Spanish, they disproportionately used adjectives culturally associated with masculinity, such as "strong" and "imposing." When the same participants described bridges in Basque, no such pattern emerged. Velasco argues that these results complicate the universalist position that conceptual categories are independent of linguistic structure, because if concepts were truly language-independent, ________', $lyceon_json$[{"key":"A","text":"the adjective choices made by the same speakers should have remained consistent regardless of which language they were using at the time of the task."},{"key":"B","text":"Basque speakers would have been unable to learn the grammatical gender system of Spanish as adult second-language learners."},{"key":"C","text":"Spanish speakers would have applied masculine adjectives to all nouns, not just those with masculine grammatical gender."},{"key":"D","text":"the bilingual participants would have preferred Basque over Spanish when asked to describe objects with no clear gender association."}]$lyceon_json$::jsonb, 'A', NULL, E'The universalist position holds that conceptual categories are independent of language. If that were true, the same speakers describing the same object should produce similar adjective patterns regardless of which language they use, since the underlying concept would be stable. The finding that adjective choices shifted depending on the language directly challenges this prediction, which is why consistent adjective choices across languages is the logical completion. The choice about Basque speakers being unable to learn Spanish gender confuses conceptual influence with learnability -- the universalist position concerns whether language shapes thought, not whether grammar systems can be acquired. The choice about Spanish speakers applying masculine adjectives to all nouns mischaracterizes the universalist prediction; the claim is about language-independence of concepts, not about overgeneralization of gender to all nouns. The choice about preferring Basque for gender-neutral objects introduces a language-preference claim that has no basis in the passage''s experimental design or the universalist position.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2VSXUYL', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'A student is writing an article for a science magazine about tardigrades and wants to emphasize the apparent contradiction between tardigrades'' physical vulnerability and their survival capabilities. Which choice most effectively uses the relevant information from the notes to accomplish this goal?
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2WXFQ05', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'The traditional view among marine biologists held that giant squid were solitary hunters that relied on ambush tactics in the deep ocean. Recent footage captured by autonomous submersibles near the Ogasawara Islands, however, has shown pairs of giant squid coordinating their movements while pursuing lanternfish schools. ______ some biologists now hypothesize that giant squid may engage in cooperative hunting behavior more frequently than previously assumed.', $lyceon_json$[{"key":"A","text":"For instance,"},{"key":"B","text":"On the other hand,"},{"key":"C","text":"Accordingly,"},{"key":"D","text":"Granted,"}]$lyceon_json$::jsonb, 'C', NULL, E'The preceding sentence presents new video evidence of paired hunting behavior, and the sentence after the blank describes a hypothesis that logically follows from that evidence. "Accordingly," correctly signals that the hypothesis is a logical consequence of the new footage. "For instance," would incorrectly frame the hypothesis as an example of the evidence rather than a conclusion drawn from it. "On the other hand," wrongly implies the hypothesis contradicts the evidence. "Granted," introduces a concession, which does not fit because the hypothesis is not being conceded but rather proposed as a result of the evidence.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2XEA205', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'A student is writing a report about coral reef conservation and wants to present a contrast between the economic value of coral reefs and the threats they face. Which choice most effectively uses the relevant information from the notes to accomplish this goal?
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ZAT57A', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'A student is writing a brief introduction about the artist Remedios Varo for a class presentation. The student wants to emphasize Varo''s international background. Which choice most effectively uses the relevant information from the notes to accomplish this goal?
